                input[2] = [] // ref
                input[3] = [] // barcodeWhitelist
                input[4] = [] // barcode
                input[5] = [] // umi
                input[6] = [] // read format
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

